package com.amit.jobagent.job;import com.amit.jobagent.common.error.ResourceNotFoundException;import java.util.UUID;import org.springframework.stereotype.Component;
@Component public class JobHandoffProvider{private final JobPostingRepository jobs;public JobHandoffProvider(JobPostingRepository jobs){this.jobs=jobs;}public JobHandoffSnapshot require(UUID id){var j=jobs.findById(id).orElseThrow(()->new ResourceNotFoundException("Job was not found"));return new JobHandoffSnapshot(j.getId(),j.title(),j.company(),j.sourceType().name(),j.canonicalApplyUrl(),j.expiresAt(),j.status(),j.contentHash());}}
